// Cypress E2E Test for SauceDemo
// Generated by Cypress Author on 2026-11-25
// Test flow: Login → Add All Items → Checkout → Logout

/// <reference types="cypress" />

describe('SauceDemo E2E Flow', () => {
  // Checkout information
  const checkoutInfo = {
    firstName: 'John',
    lastName: 'Doe',
    postalCode: '12345',
  };

  // Expected item count (SauceDemo has 6 items)
  const expectedItemCount = 6;

  beforeEach(() => {
    // Login before each test using custom command with session caching
    cy.login();
  });

  it('Login → Add ALL items to cart → Checkout → Logout', () => {
    cy.log('🧪 [TEST] Starting: Login → Add ALL items → Checkout → Logout');

    // ========== VERIFY LOGIN SUCCESS ==========
    cy.log('🔍 [TEST] Verifying login - checking inventory page');
    cy.url().should('include', '/inventory.html');
    cy.get('[data-test="title"]').should('contain', 'Products');
    cy.log('✅ [TEST] Login verified - on inventory page');
    cy.wait(1000); // Smooth video transition

    // ========== ADD ALL ITEMS TO CART ==========
    cy.log('🛒 [TEST] Adding all items to cart');
    cy.addAllItemsToCart();

    // Verify cart badge shows all items
    cy.log('🔍 [TEST] Verifying cart badge count');
    cy.get('[data-test="shopping-cart-badge"]').should('contain', expectedItemCount);

    // Verify all buttons changed to "Remove"
    cy.log('🔍 [TEST] Verifying all remove buttons visible');
    cy.get('[data-test^="remove"]').should('have.length', expectedItemCount);
    cy.log('✅ [TEST] All items added to cart');
    cy.wait(1000); // Smooth video transition

    // ========== GO TO CART ==========
    cy.log('🛍️ [TEST] Navigating to cart page');
    cy.goToCart();

    // Verify cart page shows all items
    cy.log('🔍 [TEST] Verifying cart items count');
    cy.get('.cart_item').should('have.length', expectedItemCount);
    cy.get('.inventory_item_name').should('have.length', expectedItemCount);
    cy.get('.inventory_item_price').should('have.length', expectedItemCount);
    cy.log('✅ [TEST] Cart page verified with all items');

    // Scroll down before checkout
    cy.log('📜 [TEST] Scrolling down before checkout');
    cy.scrollTo('bottom');
    cy.wait(1000); // Smooth video transition

    // ========== CHECKOUT ==========
    cy.log('💳 [TEST] Starting checkout process');
    // Click checkout button
    cy.log('🔘 [TEST] Clicking checkout button');
    cy.get('[data-test="checkout"]').click();
    cy.url().should('include', '/checkout-step-one.html');
    cy.log('✅ [TEST] On checkout step one page');
    cy.wait(1000); // Smooth video transition

    // Fill checkout information
    cy.log('📝 [TEST] Filling checkout information');
    cy.get('[data-test="firstName"]').clear().type(checkoutInfo.firstName);
    cy.get('[data-test="lastName"]').clear().type(checkoutInfo.lastName);
    cy.get('[data-test="postalCode"]').clear().type(checkoutInfo.postalCode);
    cy.log('✅ [TEST] Checkout info filled');
    cy.wait(1000); // Smooth video transition

    // Continue to overview
    cy.log('➡️ [TEST] Continuing to overview page');
    cy.get('[data-test="continue"]').click();
    cy.url().should('include', '/checkout-step-two.html');
    cy.log('✅ [TEST] On checkout overview page');
    cy.wait(1000); // Smooth video transition

    // Verify order overview - all items should be there
    cy.log('🔍 [TEST] Verifying order overview items');
    cy.get('.cart_item').should('have.length', expectedItemCount);
    cy.get('.inventory_item_name').should('have.length', expectedItemCount);
    cy.get('[data-test="subtotal-label"]').should('be.visible');
    cy.get('[data-test="tax-label"]').should('be.visible');
    cy.get('[data-test="total-label"]').should('be.visible');
    cy.log('✅ [TEST] Order overview verified');
    cy.wait(1000); // Smooth video transition

    // Finish checkout
    cy.log('🏁 [TEST] Finishing checkout');
    cy.get('[data-test="finish"]').click();
    cy.url().should('include', '/checkout-complete.html');
    cy.log('✅ [TEST] Checkout finished - on complete page');
    cy.wait(1000); // Smooth video transition

    // Verify success message
    cy.log('🔍 [TEST] Verifying success message');
    cy.contains('Thank you for your order!').should('be.visible');
    cy.get('[data-test="complete-header"]').should('contain', 'Thank you for your order!');
    cy.get('[data-test="complete-text"]').should('contain', 'Your order has been dispatched');
    cy.log('✅ [TEST] Success message verified');
    cy.wait(1000); // Smooth video transition

    // ========== LOGOUT ==========
    cy.log('🚪 [TEST] Logging out');
    // Use cy.logout() command instead of direct clicks (has force:true for menu button)
    cy.logout();

    // Verify back on login page
    cy.log('🔍 [TEST] Verifying back on login page');
    cy.url().should('eq', Cypress.config().baseUrl + '/');
    cy.get('[data-test="username"]').should('be.visible');
    cy.get('[data-test="password"]').should('be.visible');
    cy.get('[data-test="login-button"]').should('be.visible');
    cy.log('✅ [TEST] Logout verified - back on login page');
    cy.wait(1000); // Smooth video transition
  });

  it('Verify cart persistence after logout and login', () => {
    cy.log('🧪 [TEST] Starting: Cart persistence after logout and login');

    // Add all items to cart
    cy.log('🛒 [TEST] Adding all items to cart');
    cy.addAllItemsToCart();
    cy.get('[data-test="shopping-cart-badge"]').should('contain', expectedItemCount);
    cy.log('✅ [TEST] All items added to cart');

    // Logout
    cy.log('🚪 [TEST] Logging out');
    cy.logout();

    // Verify we are on login page after logout
    cy.log('🔍 [TEST] Verifying back on login page after logout');
    cy.url().should('eq', Cypress.config().baseUrl + '/');
    cy.get('[data-test="username"]').should('be.visible');
    cy.log('✅ [TEST] Logout confirmed - on login page');

    // Login again
    cy.log('🔐 [TEST] Logging in again');
    cy.login();

    // Verify we are back on inventory page
    cy.log('🔍 [TEST] Verifying back on inventory page after re-login');
    cy.url({ timeout: 15000 }).should('include', '/inventory.html');
    cy.log('✅ [TEST] Re-login successful - on inventory page');

    // Check cart state after logout/login
    // Note: SauceDemo may persist cart server-side per user
    cy.log('🔍 [TEST] Checking cart state after logout/login');
    cy.get('body').then(($body) => {
      if ($body.find('[data-test="shopping-cart-badge"]').length > 0) {
        cy.log('ℹ️ [TEST] Cart badge still present - SauceDemo persists cart per user');
        cy.get('[data-test="shopping-cart-badge"]').should('contain', expectedItemCount);
      } else {
        cy.log('ℹ️ [TEST] Cart badge not present - cart was cleared on logout');
      }
    });
    cy.log('✅ [TEST] Cart persistence test completed');
  });
});
